                                                                                                                                                                                                       
  CREATE TABLE "TENANT_FUNCTION_CONFIG"                                                                                                                                                     
   (	"CONFIG_ID" NUMBER GENERATED BY DEFAULT AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 6 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE,     
	"CREATED_BY" NUMBER(20,0),                                                                                                                                                                            
	"CREATION_DATE" DATE DEFAULT sysdate,                                                                                                                                                                 
	"UPDATED_BY" NUMBER(20,0),                                                                                                                                                                            
	"UPDATE_DATE" DATE DEFAULT sysdate,                                                                                                                                                                   
	"TENANT_ID" NUMBER(20,0) DEFAULT 3 NOT NULL ENABLE,                                                                                                                                                   
	"CODE" VARCHAR2(72) NOT NULL ENABLE,                                                                                                                                                                  
	"IS_ENABLE" NUMBER DEFAULT 0 NOT NULL ENABLE,                                                                                                                                                         
	"NAME" NVARCHAR2(100),                                                                                                                                                                                
	"BASE_DEPT_ID" NVARCHAR2(36),                                                                                                                                                                         
	 PRIMARY KEY ("CONFIG_ID")                                                                                                                                                                            
  USING INDEX  ENABLE,                                                                                                                                                                                 
	 CONSTRAINT "TENANT_FUNCTION_CONFIG_CODE_TENANT_ID" UNIQUE ("CODE", "BASE_DEPT_ID", "TENANT_ID")                                                                                                      
  USING INDEX  ENABLE                                                                                                                                                                                  
   ) ;                                                                                                                                                                                                 

